// 每次原交付开工只一个永久接触头；实际Common结果/末history生成后才绑定，不改原ActionStarted。
#include "task_shop_order_contact_receipts.hpp"
#include "task_shop_order_contact_detail.hpp"
#include "resident/kernel/command_types.hpp"
#include <set>
namespace hanmo::resident {namespace {
constexpr const char* command="task_shop_order_deliver";
Status matches(const TaskShopOrderContactStart& o,const StableId& actor,const StableId& kind,Integer tick,const ReceiptDetails& details){const auto* action=std::get_if<ActionStarted>(&details.data);if(kind!=command||o.proprietor_actor_id!=actor||o.started_tick!=tick||!action||action->action_id!=o.action_id)return common_failure("TaskShopOrderContactActualSourceRequired",o.fact_id);return common_success();}
Status bindings(const CommonStore& common,const TaskShopOrderContactState& state){Integer last_result=0,last_revision=0;std::map<StableId,Integer> requests;std::set<StableId> results;
    // 缓存全裁后仍不能把另一真实业务头的全局实例号改称result；只比较规范单段实例。
    std::set<Integer> fact_instances;for(const auto& row:common.state().facts.rows()){const auto split=row.first.find(':');if(split==StableId::npos)continue;auto number=shop_contact_detail::serial(common,row.first,row.first.substr(0,split));if(number)fact_instances.insert(*number);}
    for(const auto& row:state.starts.rows()){const auto& o=row.second;if(!o.actual_result)return common_failure("TaskShopOrderContactPermanentResultRequired",row.first);const auto& b=*o.actual_result;const auto fact=shop_contact_detail::serial(common,row.first,task_shop_order_contact_started_kind),result=shop_contact_detail::serial(common,b.result_id,"result");const auto* head=common.state().facts.find(row.first);const auto* seq=common.state().request_sequences.find(b.request_actor_id);
        if(o.fact_id!=row.first||!head||head->id!=row.first||head->kind!=task_shop_order_contact_started_kind||head->domain!=task_shop_order_contact_module||!fact||!result||*fact<=last_result||*result<=*fact||fact_instances.count(*result)||b.request_actor_id!=o.proprietor_actor_id||!seq||b.request_sequence<1||b.request_sequence>2147483647||b.request_sequence>*seq||b.request_sequence<=requests[b.request_actor_id]||b.result_revision<=last_revision||b.result_revision>common.revision()||!results.insert(b.result_id).second)return common_failure("InvalidTaskShopOrderContactPlayerBinding",row.first);last_result=*result;last_revision=b.result_revision;requests[b.request_actor_id]=b.request_sequence;
        const HistoryRecord* previous=nullptr;const HistoryRecord* lower=nullptr;std::size_t count=0;for(const auto& h:common.state().history){if(h.result_id==b.result_id){lower=previous;if(++count>1||h.actor_id!=b.request_actor_id||h.kind!=command||h.tick!=o.started_tick)return common_failure("TaskShopOrderContactPlayerHistoryMismatch",row.first);}previous=&h;}if(lower){auto bound=shop_contact_detail::serial(common,lower->result_id,"result");if(!bound||*bound>=*fact)return common_failure("TaskShopOrderContactAllocationMismatch",row.first);}
        const auto* cached=common.state().results.find(b.request_actor_id+":"+std::to_string(b.request_sequence));if(cached){if(count!=1||!*cached||!(*cached)->ok||!(*cached)->details||(*cached)->result_id!=b.result_id||(*cached)->revision!=b.result_revision)return common_failure("TaskShopOrderContactPlayerCacheMismatch",row.first);auto valid=matches(o,b.request_actor_id,(*cached)->kind,(*cached)->tick,*(*cached)->details);if(!valid.ok)return valid;}
    }return common_success();}
}
Outcome<StableId> task_shop_order_contact_new_result_source(const TaskShopOrderContactState* before,const TaskShopOrderContactState* after,const StableId& actor,const StableId& kind,const ReceiptDetails& details,Integer tick){auto fail=[]()->Outcome<StableId>{return {false,{},common_failure("TaskShopOrderContactNewSourceRequired").error};};if(!after){if(before||kind==command)return fail();return {true,{}, {}};}if(!before||before->version!=1||after->version!=1||after->starts.size()<before->starts.size())return fail();
    for(std::size_t n=0;n<before->starts.size();++n){const auto& id=before->starts.order()[n];const auto* old=before->starts.find(id);if(!old||!old->actual_result||after->starts.order()[n]!=id)return fail();auto a=encode_task_shop_order_contact_fact(*before,id),b=encode_task_shop_order_contact_fact(*after,id);if(!a.ok||!b.ok||!compare_boundary(a.value,b.value).exact())return fail();}
    const auto added=after->starts.size()-before->starts.size();if(kind!=command)return added?fail():Outcome<StableId>{true,{}, {}};if(added!=1)return fail();const auto& row=after->starts.rows().back();if(row.second.actual_result)return fail();auto valid=matches(row.second,actor,kind,tick,details);return valid.ok?Outcome<StableId>{true,row.first,{}}:Outcome<StableId>{false,{},valid.error};
}
Status bind_task_shop_order_contact_result(CommonStore& common,TaskShopOrderContactState& state,const StableId& id,const StableId& actor,Integer request,const CommitResult& result){if(id.empty())return result.kind==command?common_failure("TaskShopOrderContactNewSourceRequired"):common_success();auto* o=state.starts.find(id);const auto* cached=common.state().results.find(actor+":"+std::to_string(request));const auto* seq=common.state().request_sequences.find(actor);if(!o||o->actual_result||!result.ok||!result.details||result.tick!=common.tick()||result.revision!=common.revision()||!cached||cached->get()!=&result||!seq||*seq!=request||common.state().history.empty())return common_failure("TaskShopOrderContactActualPlayerResultRequired",id);const auto& h=common.state().history.back();if(h.result_id!=result.result_id||h.actor_id!=actor||h.kind!=command||h.tick!=result.tick)return common_failure("TaskShopOrderContactActualPlayerHistoryRequired",id);auto valid=matches(*o,actor,result.kind,result.tick,*result.details);if(!valid.ok)return valid;o->actual_result=TaskShopOrderContactResult{result.result_id,actor,request,result.revision};valid=bindings(common,state);if(!valid.ok)o->actual_result.reset();return valid;}
Status validate_task_shop_order_contact_results(const CommonStore& common,const TaskShopOrderContactState& state){
 if(state.version!=1)return common_failure("UnsupportedTaskShopOrderContactVersion");auto valid=bindings(common,state);if(!valid.ok)return valid;std::set<StableId> used;
 for(const auto& row:common.state().results.rows()){if(!row.second||row.second->kind!=command)continue;const auto& result=*row.second;const auto* action=result.details?std::get_if<ActionStarted>(&result.details->data):nullptr;if(!result.ok||!action)return common_failure("TaskShopOrderContactCachedActionRequired",row.first);const TaskShopOrderContactStart* source=nullptr;for(const auto& entry:state.starts.rows())if(entry.second.action_id==action->action_id){if(source)return common_failure("DuplicateTaskShopOrderContact",row.first);source=&entry.second;}if(!source||!source->actual_result||!used.insert(source->fact_id).second)return common_failure("TaskShopOrderContactCachedSourceRequired",row.first);const auto& p=*source->actual_result;if(row.first!=p.request_actor_id+":"+std::to_string(p.request_sequence)||p.result_id!=result.result_id||p.result_revision!=result.revision)return common_failure("TaskShopOrderContactCachedBindingMismatch",row.first);valid=matches(*source,p.request_actor_id,result.kind,result.tick,*result.details);if(!valid.ok)return valid;}
 return common_success();
}
}
